import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"文献综述","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/reviews.md","filePath":"zh/guide/reviews.md","lastUpdated":1791997268000}'),n={name:"zh/guide/reviews.md"};function s(i,a,l,h,p,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="文献综述" tabindex="-1">文献综述 <a class="header-anchor" href="#文献综述" aria-label="Permalink to &quot;文献综述&quot;">​</a></h1><p><strong>实验性功能。</strong> 将选定文献的摘要证据组织成主题大纲，生成可编辑且带引用的草稿。</p><p>该功能使用已有论文与摘要，不会自动读取完整 PDF。请对照原始研究核查草稿。</p><h2 id="模块与证据" tabindex="-1">模块与证据 <a class="header-anchor" href="#模块与证据" aria-label="Permalink to &quot;模块与证据&quot;">​</a></h2><p>综述包含文献、大纲、正文和引用证据四个子页。当前综述的模型配置在综述页的模型折叠区中调整，生成期间不能修改。历史侧栏只显示综述；引用证据集中提供段落引文与文献关系图。新综述独立保存可用的来源图快照，旧综述仍可能依赖来源检索。</p><h2 id="_1-选择证据" tabindex="-1">1. 选择证据 <a class="header-anchor" href="#_1-选择证据" aria-label="Permalink to &quot;1. 选择证据&quot;">​</a></h2><p>从结果勾选后进入，或打开<strong>综述 → 新建综述</strong>，选择已有检索。</p><p>选择 <strong>2–100 篇</strong>摘要充分且与主题相关的论文。文献更多不代表证据更好，缺乏有效研究内容的记录可能不会参与正文。</p><p>在线综述需要登录和已保存的来源检索；社区版保存在本地。</p><h2 id="_2-设置范围" tabindex="-1">2. 设置范围 <a class="header-anchor" href="#_2-设置范围" aria-label="Permalink to &quot;2. 设置范围&quot;">​</a></h2><p>填写主题，选择中文或英文，以及简短、标准或详细。</p><p>默认章节数分别为 <strong>1、3、6</strong>，可自定义 <strong>1–14 章</strong>。这不保证固定字数，证据与大纲决定了适合写作的内容。</p><p>社区版和在线版自带密钥模式可以配置写作模型，PaperSeek 服务从允许的模型中选择。</p><h2 id="_3-检查大纲" tabindex="-1">3. 检查大纲 <a class="header-anchor" href="#_3-检查大纲" aria-label="Permalink to &quot;3. 检查大纲&quot;">​</a></h2><p>审阅主题、章节结构、段落计划和文献分配，检查遗漏视角及超出证据的写作范围。</p><p>点击<strong>保存大纲</strong>只保存修改，不启动写作；准备好生成正文后，再点击<strong>确认大纲并执行</strong>或<strong>保存大纲并执行</strong>。离开未保存的编辑时，会提示继续编辑或放弃修改。</p><h2 id="_4-阅读与修订" tabindex="-1">4. 阅读与修订 <a class="header-anchor" href="#_4-阅读与修订" aria-label="Permalink to &quot;4. 阅读与修订&quot;">​</a></h2><p>可以编辑文字、单节重写并查看可用版本。修改大纲不会自动让旧正文与新大纲一致，应检查当前版本和任务状态。</p><p>引文可选择顺序编号或 Harvard 作者—年份，导出沿用所选呈现方式。</p><p>证据检查能提示支撑不足或不一致，但不能证明科学结论正确。依赖论断前仍需阅读原始论文。</p><h2 id="_5-导出" tabindex="-1">5. 导出 <a class="header-anchor" href="#_5-导出" aria-label="Permalink to &quot;5. 导出&quot;">​</a></h2><ul><li><strong>Markdown</strong>：继续编辑。</li><li><strong>Word（.docx）</strong>：文档写作。</li><li><strong>BibTeX</strong>：管理参考文献。</li></ul><h2 id="生成中断时" tabindex="-1">生成中断时 <a class="header-anchor" href="#生成中断时" aria-label="Permalink to &quot;生成中断时&quot;">​</a></h2><p>当前或最近任务的状态与已保存正文分开展示，停止任务不会抹除大纲或已经完成的章节。模型访问、余额、超时和结构化响应错误可能导致大纲或正文中断。修正原因后重试受影响操作，不必创建重复综述。</p><p>刷新连接已保存状态，不会重启生成。在线写作与检索共用<a href="./../online/#任务排队">执行队列</a>。</p>',25)])])}const g=e(n,[["render",s]]);export{c as __pageData,g as default};
